	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void timedEvictionRunsOnlyInDurableMode(boolean asynchronous, @TempDir Path directory) throws Exception {
		LmdbStoreConfig config = config(asynchronous);
		try (ClosingValueStore values = new ClosingValueStore(directory, config)) {
			Value original = VF.createBNode("timed-retirement");
			long id = store(values, original);
			values.startTransaction(true);
			values.gcIds(Set.of(id), new HashSet<>());
			values.commit();

			// Mutating the caller's config cannot live-switch an already-open ValueStore.
			config.setAsyncValueCleanup(!asynchronous);
			values.forceEvictionOfValues();
			values.startTransaction(true);
			values.commit();
			if (asynchronous) {
				assertEquals(original, values.getValue(id),
						"foreground admission must preserve pending reverse records");
				assertEquals(1, values.reclaimPersistedUnusedIdsBatch(1));
			}
			assertNull(values.getValue(id));
		}
	}

	@Test
	void cleanupIdentityAllowsForwardRetirementButPreventsNumericReuse(@TempDir Path directory) throws Exception {
		try (ClosingValueStore values = new ClosingValueStore(directory, config(true))) {
			Value original = VF.createBNode("old-identity");
			long id;
			try (ValueStore.CleanupReservation reservation = values.reserveCleanupIdentity()) {
				id = store(values, original);
				values.startTransaction(true);
				values.gcIds(List.of(id, id), new HashSet<>());
				values.commit();
				assertEquals(LmdbValue.UNKNOWN_ID, values.getId(original));
				assertTrue(reservation.isCurrent());
				assertEquals(0, values.reclaimPersistedUnusedIdsBatch(1));
				assertEquals(original, values.getValue(id));
				assertNotEquals(id, store(values, VF.createBNode("another-identity")),
						"an unacknowledged candidate cannot be recycled into another record");
			}
			assertEquals(1, values.reclaimPersistedUnusedIdsBatch(1));
			assertNull(values.getValue(id));
			assertEquals(id, store(values, VF.createBNode("recycled-after-ack")),
					"closing cleanup identity preserves the existing guarded reuse path");
		}
	}

	@Test
	void duplicateCandidatesDecrementDependencyCountsOnce(@TempDir Path directory) throws Exception {
		try (ClosingValueStore values = new ClosingValueStore(directory, config(true));
				ValueStore.CleanupReservation reservation = values.reserveCleanupIdentity()) {
			IRI datatype = VF.createIRI("urn:async-cleanup:datatype");
			long first = store(values, VF.createLiteral("first", datatype));
			long second = store(values, VF.createLiteral("second", datatype));
			long datatypeId = values.getId(datatype);
			Set<Long> dependencies = new HashSet<>();
			values.startTransaction(true);
			values.gcIds(List.of(first, first), dependencies);
			values.commit();
			assertTrue(dependencies.isEmpty(), "the remaining literal still owns the datatype");
			values.startTransaction(true);
			values.gcIds(Set.of(first), dependencies);
			values.commit();
			assertTrue(dependencies.isEmpty(), "batch replay must not repeat the dependency decrement");
			values.startTransaction(true);
			values.gcIds(Set.of(second), dependencies);
			values.commit();
			assertEquals(Set.of(datatypeId), dependencies);
		}
	}

	@Test
	void currentDurableIntentIsRemovedAtomicallyWithAsyncRetirement(@TempDir Path directory) throws Exception {
		try (ClosingValueStore values = new ClosingValueStore(directory, config(true));
				ValueStore.CleanupReservation reservation = values.reserveCleanupIdentity()) {
			Value original = VF.createBNode("legacy-backlog");
			long id = store(values, original);
			for (long revision : new long[] { 3L, 4L }) {
				values.startTransaction(true);
				values.recordRetiredIds(Set.of(id), revision);
				values.commit();
			}
			values.startTransaction(true);
			values.gcIds(Set.of(id), new HashSet<>());
			values.removeAsyncRetiredIds(Set.of(id));
			values.rollback();
			assertEquals(id, values.getId(original));
			assertEquals(List.of(id), values.pollRetiredIds(Long.MAX_VALUE, 16).ids,
					"an aborted maintenance commit must retain its current durable authority");

			values.startTransaction(true);
			values.gcIds(Set.of(id), new HashSet<>());
			values.removeAsyncRetiredIds(Set.of(id));
			values.commit();
			RetiredValueIdStore.DrainBatch remaining = values.pollRetiredIds(Long.MAX_VALUE, 16);
			assertNotNull(remaining);
			assertTrue(remaining.ids.isEmpty(), "the surviving sequence entry is superseded, never reclaim authority");
			assertEquals(1, remaining.staleSeqKeys.size());
			values.startTransaction(true);
			values.removeRetiredIds(remaining);
			values.commit();
			assertFalse(values.hasRetiredIds());
		}
	}

