	@Test
	void spoolIdentityUsesExistingGenerationAndExactClosedNativeTransaction(@TempDir Path directory) throws Exception {
		byte[] identity;
		long beforeClose;
		long finalTransaction;
		ClosingValueStore first = new ClosingValueStore(directory, config(true));
		try {
			store(first, VF.createBNode("spooled"));
			identity = first.cleanupStoreIdentity();
			assertEquals(ReferenceCountProof.GENERATION_BYTES, identity.length);
			byte[] attemptedMutation = first.cleanupStoreIdentity();
			attemptedMutation[0] ^= 1;
			assertArrayEquals(identity, first.cleanupStoreIdentity());
			beforeClose = first.cleanupTransactionId();
		} finally {
			first.close();
		}
		finalTransaction = first.cleanupTransactionId();
		assertTrue(finalTransaction > beforeClose, "the final clean marker is an additional native transaction");
		try (ClosingValueStore reopened = new ClosingValueStore(directory, config(false))) {
			assertArrayEquals(identity, reopened.cleanupStoreIdentity(),
					"changing reclamation mode keeps the dictionary");
			assertEquals(finalTransaction, reopened.cleanupStartupTransactionId(),
					"startup bootstrap writes must not overwrite the saved replay identity");
			assertTrue(reopened.cleanupTransactionId() > reopened.cleanupStartupTransactionId());
		}
	}

