	@Test
	void cleanupOfALargeLiteralDoesNotCopyItsLexicalRecord(@TempDir Path directory) throws Exception {
		Assumptions.assumeTrue(ManagementFactory.getThreadMXBean() instanceof com.sun.management.ThreadMXBean);
		com.sun.management.ThreadMXBean allocations = (com.sun.management.ThreadMXBean) ManagementFactory
				.getThreadMXBean();
		Assumptions.assumeTrue(allocations.isThreadAllocatedMemorySupported());
		allocations.setThreadAllocatedMemoryEnabled(true);
		int lexicalBytes = 8 * 1024 * 1024;
		try (ClosingValueStore values = new ClosingValueStore(directory, config(true))) {
			long id = store(values, VF.createLiteral("x".repeat(lexicalBytes), VF.createIRI("urn:large:datatype")));
			values.startTransaction(true);
			long before = allocations.getCurrentThreadAllocatedBytes();
			values.gcIds(Set.of(id), new HashSet<>());
			values.commit();
			long forwardBytes = allocations.getCurrentThreadAllocatedBytes() - before;
			assertTrue(forwardBytes < lexicalBytes / 2,
					"forward cleanup must hash the native buffer without copying a large literal: " + forwardBytes);
			before = allocations.getCurrentThreadAllocatedBytes();
			assertEquals(1, values.reclaimPersistedUnusedIdsBatch(1));
			long reverseBytes = allocations.getCurrentThreadAllocatedBytes() - before;
			assertTrue(reverseBytes < lexicalBytes / 2,
					"physical cleanup must check the record type without copying its lexical bytes: " + reverseBytes);
			assertTrue(values.lastBoundedUnusedReclamationMadeProgress());
			assertNull(values.getValue(id));
			assertEquals(0, values.reclaimPersistedUnusedIdsBatch(1));
			assertFalse(values.lastBoundedUnusedReclamationMadeProgress());
		}
	}

