	@Test
	void optionalNativeDeleteMetricsCountAttemptsAndRemainReadableAfterClose(@TempDir Path directory)
			throws Exception {
		ClosingValueStore values = new ClosingValueStore(directory, config(true));
		try {
			long id = store(values, VF.createBNode("native-counter"));
			assertEquals(new ValueStore.CleanupNativeMetrics(0L, 0L), values.cleanupNativeMetrics());
			values.enableCleanupNativeMetrics();
			values.startTransaction(true);
			values.recordRetiredIds(Set.of(id), 1L);
			values.commit();
			ValueStore.CleanupNativeMetrics before = values.cleanupNativeMetrics();
			values.startTransaction(true);
			values.gcIds(Set.of(id), new HashSet<>());
			values.removeAsyncRetiredIds(Set.of(id));
			values.rollback();
			ValueStore.CleanupNativeMetrics after = values.cleanupNativeMetrics();
			assertEquals(3L, after.attemptedDeletes() - before.attemptedDeletes(),
					"forward mapping and both retirement keys each invoke one native delete, even on abort");
			assertEquals(3L, after.successfulDeletes() - before.successfulDeletes());
			assertEquals(id, values.getId(VF.createBNode("native-counter")),
					"native attempts are not committed deletes");
		} finally {
			values.close();
		}
		assertTrue(values.cleanupNativeMetrics().attemptedDeletes() >= 3L);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void concurrentCanonicalPublicationKeepsOldEpochsSeparateAcrossCleanup(boolean asynchronous,
			@TempDir Path directory) throws Exception {
		IRI subject = VF.createIRI("urn:cache:subject");
		IRI predicate = VF.createIRI("urn:cache:predicate");
		Value expected = VF.createTripleTerm(subject, predicate,
				VF.createTripleTerm(subject, predicate, VF.createLiteral("cold nested payload")));
		try (ClosingValueStore values = new ClosingValueStore(directory, config(asynchronous).setValueCacheSize(64));
				var executor = Executors.newFixedThreadPool(4)) {
			long id = store(values, expected);
			CountDownLatch lookedUp = new CountDownLatch(4);
			CountDownLatch decode = new CountDownLatch(1);
			List<LmdbValue> shells = new CopyOnWriteArrayList<>();
			List<Future<LmdbValue>> results = new ArrayList<>();
			for (int i = 0; i < 4; i++) {
				results.add(executor.submit(() -> {
					LmdbValue shell = values.getLazyValue(id);
					shells.add(shell);
					lookedUp.countDown();
					assertTrue(decode.await(10, TimeUnit.SECONDS));
					shell.init();
					return shell;
				}));
			}
			LmdbValue current;
			try {
				assertTrue(lookedUp.await(10, TimeUnit.SECONDS));
				for (LmdbValue shell : shells) {
					assertSame(shells.getFirst(), shell,
							"first concurrent array publication must share one canonical shell");
				}
				values.startTransaction(true);
				values.gcIds(Set.of(id), new HashSet<>());
				values.commit();
				current = values.getLazyValue(id);
				assertNotSame(shells.getFirst(), current, "a cleanup epoch cannot reuse the old canonical array");
			} finally {
				decode.countDown();
			}
			for (Future<LmdbValue> result : results) {
				assertSame(shells.getFirst(), result.get(10, TimeUnit.SECONDS));
				assertEquals(expected, result.get());
			}
			current.init();
			assertEquals(expected, current);
			assertSame(current, values.getLazyValue(id));
			assertSame(current, values.getValue(id), "late old-epoch completion cannot overwrite the current cache");
		}
	}

	@Test
	void boundedCleanupRetiresOptionalOverlayWithoutCopyingLargePayloads(@TempDir Path directory) throws Exception {
		Assumptions.assumeTrue(ManagementFactory.getThreadMXBean() instanceof com.sun.management.ThreadMXBean);
		com.sun.management.ThreadMXBean allocations = (com.sun.management.ThreadMXBean) ManagementFactory
				.getThreadMXBean();
		Assumptions.assumeTrue(allocations.isThreadAllocatedMemorySupported());
		allocations.setThreadAllocatedMemoryEnabled(true);
		int lexicalBytes = 512 * 1024;
		Value literal = VF.createLiteral("z".repeat(lexicalBytes), VF.createIRI("urn:overlay:datatype"));
		CompressedValueOverlay.Options options = new CompressedValueOverlay.Options(32L << 20, 8192, 16,
				64 << 10, 1 << 20, true, true);
		try (ClosingValueStore values = new ClosingValueStore(directory, config(true).setValueOverlayEnabled(true))) {
			long id = store(values, literal);
			var base = values.warmCompressedValueOverlay(options);
			assertNotNull(base);
			try (ValueStore.ReadSnapshotReservation reservation = values.reserveReadSnapshot();
					ValueStore.ReadSnapshot snapshot = reservation.start()) {
				assertEquals(id, values.getId(snapshot, literal));
				values.startTransaction(true);
				values.gcIds(Set.of(id), new HashSet<>());
				values.rollback();
				assertSame(base, values.compressedValueOverlayStats(),
						"an aborted maintenance transaction keeps its overlay");
				values.startTransaction(true);
				long before = allocations.getCurrentThreadAllocatedBytes();
				values.gcIds(Set.of(id), new HashSet<>());
				values.commit();
				long allocated = allocations.getCurrentThreadAllocatedBytes() - before;
				assertTrue(allocated < lexicalBytes / 2,
						"bounded cleanup must not copy lexical payloads into optional overlay deltas: " + allocated);
				assertNull(values.compressedValueOverlayStats(),
						"the new current view falls back to its native dictionary");
				assertEquals(LmdbValue.UNKNOWN_ID, values.getId(literal));
				assertEquals(id, values.getId(snapshot, literal),
						"the existing snapshot retains its exact old dictionary");
				assertEquals(literal, values.getValue(snapshot, id));
			}
			assertNotNull(values.warmCompressedValueOverlay(options));
			assertEquals(1, values.reclaimPersistedUnusedIdsBatch(1));
			assertNull(values.compressedValueOverlayStats(), "physical cleanup also retires its derived current view");
		}
	}

	@Test
	void observingProducerIdentityAdmissionDoesNotWaitForNativePublication(@TempDir Path directory) throws Exception {
		try (ClosingValueStore values = new ClosingValueStore(directory, config(true));
				var executor = Executors.newSingleThreadExecutor()) {
			Field field = ValueStore.class.getDeclaredField("associationGate");
			field.setAccessible(true);
			ReentrantLock publication = (ReentrantLock) field.get(values);
			CountDownLatch entered = new CountDownLatch(1);
			CountDownLatch release = new CountDownLatch(1);
			Future<?> publisher = executor.submit(() -> {
				publication.lock();
				try {
					entered.countDown();
					assertTrue(release.await(10, TimeUnit.SECONDS));
					return null;
				} finally {
					publication.unlock();
				}
			});
			try {
				assertTrue(entered.await(10, TimeUnit.SECONDS));
				assertThrows(IOException.class, () -> values.reserveCleanupIdentity(false));
			} finally {
				release.countDown();
			}
			publisher.get(10, TimeUnit.SECONDS);
			try (ValueStore.CleanupReservation reservation = values.reserveCleanupIdentity(false)) {
				assertTrue(reservation.isCurrent());
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void replayedCurrentRetirementPinsAnAlreadyUnusedNumericId(boolean asynchronous, @TempDir Path directory)
			throws Exception {
		try (ClosingValueStore values = new ClosingValueStore(directory, config(asynchronous))) {
			Value original = VF.createBNode("already-acknowledged-spool-prefix");
			long id = store(values, original);
			byte[] originalRecord = values.getData(id);
			values.startTransaction(true);
			values.gcIds(Set.of(id), new HashSet<>());
			values.commit();
			// A partially processed saved stream can replay this prefix into durable mode or a protected-value
			// continuation. Its current retirement intent must disappear before the unused numeric ID is reusable.
			values.startTransaction(true);
			values.recordRetiredIds(Set.of(id), 7L);
			values.commit();
			assertEquals(1, values.reclaimPersistedUnusedIdsBatch(1));
			assertFalse(values.lastBoundedUnusedReclamationMadeProgress());
			assertArrayEquals(originalRecord, values.getData(id));
			assertNotEquals(id, store(values, VF.createBNode("different-record")));
			RetiredValueIdStore.DrainBatch batch = values.pollRetiredIds(Long.MAX_VALUE, 1);
			values.startTransaction(true);
			values.gcIds(batch.ids, new HashSet<>());
			values.removeRetiredIds(batch);
			values.commit();
			assertFalse(values.hasRetiredIds());
			assertEquals(1, values.reclaimPersistedUnusedIdsBatch(1));
			assertTrue(values.lastBoundedUnusedReclamationMadeProgress());
			assertNull(values.getValue(id));
		}
	}

	private static long store(ValueStore values, Value value) throws IOException {
		values.startTransaction(true);
		long id = values.storeValue(value);
		values.commit();
		return id;
	}

	private static LmdbStoreConfig config(boolean asynchronous) {
		return new LmdbStoreConfig().setAsyncValueCleanup(asynchronous)
				.setValueDBSize(32L * 1024 * 1024)
				.setValueOverlayEnabled(false);
	}

	private static final class ClosingValueStore extends ValueStore implements AutoCloseable {
		private ClosingValueStore(Path directory, LmdbStoreConfig config) throws IOException {
			super(new File(directory.toFile(), "values"), config);
			completeStoreInitialization(ids -> {
				// This fixture contains dictionary records and no statements.
			});
		}
	}
